css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); border-radius: 50%; border: calc(var(--loader-size) * .03) solid color-mix(in srgb, var(--accent-2) 40%, transparent); position: relative; overflow: hidden; }
.loader::before { content: ''; position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(from 0deg, transparent 0deg, color-mix(in srgb, var(--accent) 65%, transparent) 55deg, transparent 70deg); animation: radar calc(var(--loader-speed) * 1.6) linear infinite; }
.loader::after { content: ''; position: absolute; left: 50%; top: 50%; width: 9%; height: 9%; margin: -4.5% 0 0 -4.5%; border-radius: 50%; background: var(--accent); }
@keyframes radar { to { transform: rotate(360deg); } }
